import os,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in __import__('re').finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
demo_in=G['Demo pair 1 input']; demo_out=G['Demo pair 1 output']

def transform(grid):
    import collections
    h,w=len(grid),len(grid[0])
    bg=collections.Counter(x for r in grid for x in r).most_common(1)[0][0]
    g=[r[:] for r in grid]
    seen=[[False]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg or seen[i][j]: continue
            c=g[i][j]; stack=[(i,j)]; comp=[]; seen[i][j]=True
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]==c:
                        seen[ny][nx]=True; stack.append((ny,nx))
            if len(comp)>=4:
                ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
                for y in range(min(ys),max(ys)+1):
                    for x in range(min(xs),max(xs)+1):
                        g[y][x]=c
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg: g[i][j]=bg
    return g
r=transform(demo_in)
print(r==demo_out)
if r!=demo_out:
    for a,b in zip(r,demo_out):
        if a!=b: print(a,b)

